        selected.setShape(0);
        selected.setCornerRadius(radius);
        selected.setColor(0x3D8B5CF6);
        selected.setStroke(Math.max(1, Math.round(dp(ctx, 1.5f))), 0xE68B5CF6);
        GradientDrawable pressed = new GradientDrawable();
        pressed.setShape(0);
        pressed.setCornerRadius(radius);
        pressed.setColor(0x2E8B5CF6);
        pressed.setStroke(stroke, 0x8C8B5CF6);
        GradientDrawable normal = new GradientDrawable();
        normal.setShape(0);
        normal.setCornerRadius(radius);
        normal.setColor(0x59141834);
        normal.setStroke(stroke, 0x2E8B5CF6);
        StateListDrawable s = new StateListDrawable();
        s.addState(new int[]{R.attr.state_selected}, selected);
        s.addState(new int[]{R.attr.state_pressed}, pressed);
        s.addState(new int[0], normal);
