    public static Drawable seekProgress(Context ctx) {
        int h = Math.max(1, Math.round(dp(ctx, 4.0f)));
        float r = dp(ctx, 999.0f);
        GradientDrawable bg = new GradientDrawable();
        bg.setShape(0);
        bg.setCornerRadius(r);
        // 轨道＝深色蓝紫；已完成＝星光紫渐变（深紫→柔和紫）
        bg.setColor(INDIGO_1);
        bg.setSize(0, h);
        GradientDrawable sec = new GradientDrawable();
        sec.setShape(0);
        sec.setCornerRadius(r);
        sec.setColor(0x4D8B5CF6);
        sec.setSize(0, h);
        GradientDrawable prog = new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,
                new int[]{BRAND_DEEP, BRAND, BRAND_SOFT});
        prog.setShape(0);
        prog.setCornerRadius(r);
        prog.setSize(0, h);
        LayerDrawable layer = new LayerDrawable(new Drawable[]{bg, new ClipDrawable(sec, 0x00800003, 1), new ClipDrawable(prog, 0x00800003, 1)});
        layer.setId(0, R.id.background);
        layer.setId(1, R.id.secondaryProgress);
        layer.setId(2, R.id.progress);
        return layer;
    }

