    private static final class CatOrnamentDrawable extends Drawable {
        private final Paint line = new Paint(1);
        private final Paint fill = new Paint(1);
        private final Path path = new Path();

        CatOrnamentDrawable() {
            this.fill.setStyle(Paint.Style.FILL);
            this.line.setStyle(Paint.Style.STROKE);
            this.line.setStrokeCap(Paint.Cap.ROUND);
        }

        @Override // android.graphics.drawable.Drawable
        public void draw(Canvas canvas) {
            Rect b = getBounds();
            if (b.isEmpty()) {
                return;
            }
            float sx = b.width() / 96.0f;
            float sy = b.height() / 24.0f;
            canvas.save();
            canvas.translate(b.left, b.top);
            canvas.scale(sx, sy);
            this.line.setStrokeWidth(1.4f);
            this.line.setShader(new LinearGradient(0.0f, 12.0f, 34.0f, 12.0f, 0x008B5CF6, 0xCC8B5CF6, Shader.TileMode.CLAMP));
            canvas.drawLine(0.0f, 12.0f, 34.0f, 12.0f, this.line);
            this.line.setShader(new LinearGradient(62.0f, 12.0f, 96.0f, 12.0f, 0xCC8B5CF6, 0x008B5CF6, Shader.TileMode.CLAMP));
            canvas.drawLine(62.0f, 12.0f, 96.0f, 12.0f, this.line);
            this.line.setShader(null);
            drawSpark(canvas, 48.0f, 12.0f, 9.5f, 0x3D8B5CF6);
            drawSpark(canvas, 48.0f, 12.0f, 7.0f, MagicRes.BRAND_SOFT);
            this.fill.setColor(0xFFF4EEFF);
            canvas.drawCircle(48.0f, 12.0f, 1.5f, this.fill);
            drawSpark(canvas, 60.0f, 6.5f, 2.6f, 0x8CA78BFA);
            drawSpark(canvas, 36.0f, 17.5f, 2.2f, 0x73A78BFA);
            canvas.restore();
        }

        private void drawSpark(Canvas c, float cx, float cy, float r, int color) {
            float k = 0.32f * r;
            this.fill.setColor(color);
            this.path.reset();
            this.path.moveTo(cx, cy - r);
            this.path.lineTo(cx + k, cy - k);
            this.path.lineTo(cx + r, cy);
            this.path.lineTo(cx + k, cy + k);
            this.path.lineTo(cx, cy + r);
            this.path.lineTo(cx - k, cy + k);
            this.path.lineTo(cx - r, cy);
            this.path.lineTo(cx - k, cy - k);
            this.path.close();
            c.drawPath(this.path, this.fill);
        }

        @Override // android.graphics.drawable.Drawable
        public void setAlpha(int alpha) {
            this.line.setAlpha(alpha);
            this.fill.setAlpha(alpha);
            invalidateSelf();
        }

        @Override // android.graphics.drawable.Drawable
        public void setColorFilter(ColorFilter colorFilter) {
            this.line.setColorFilter(colorFilter);
            this.fill.setColorFilter(colorFilter);
            invalidateSelf();
        }

        @Override // android.graphics.drawable.Drawable
        public int getOpacity() {
            return -3;
        }

        @Override // android.graphics.drawable.Drawable
        public int getIntrinsicWidth() {
            return -1;
        }

        @Override // android.graphics.drawable.Drawable
        public int getIntrinsicHeight() {
            return -1;
        }
    }

